    vector<vector<int>> mergeOverlap(vector<vector<int>>& arr) {
        vector<vector<int>> ans;
        int n = arr.size();

        sort(arr.begin(), arr.end());

        for (int i = 0; i < n; ) {
            int minVal = arr[i][0];
            int maxVal = arr[i][1];

            int idx = i + 1;

            while (idx < n && arr[idx][0] <= maxVal) {
                maxVal = max(maxVal, arr[idx][1]);
                idx++;
            }

            ans.push_back({minVal, maxVal});
            i = idx;
        }

        return ans;
    }
};
